CREATE TABLE public.agente_gerencial_acessos (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE);
GRANT SELECT ON public.agente_gerencial_acessos TO authenticated;
GRANT ALL ON public.agente_gerencial_acessos TO service_role;
ALTER TABLE public.agente_gerencial_acessos ENABLE ROW LEVEL SECURITY;
CREATE POLICY acesso_proprio ON public.agente_gerencial_acessos FOR SELECT TO authenticated USING (user_id = auth.uid());
INSERT INTO public.agente_gerencial_acessos(user_id) SELECT id FROM public.profiles WHERE id='e847b0ab-5e6f-417e-8115-6d2c67a3697f';
CREATE FUNCTION public.pode_agente_gerencial() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (SELECT public.is_active_operator()) AND ((SELECT public.is_admin()) OR EXISTS (SELECT 1 FROM public.agente_gerencial_acessos WHERE user_id=auth.uid())) $$;
REVOKE ALL ON FUNCTION public.pode_agente_gerencial() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pode_agente_gerencial() TO authenticated,service_role;
CREATE TABLE public.agente_gerencial_conversas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, titulo text NOT NULL DEFAULT 'Nova conversa', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), executando_em timestamptz);
GRANT SELECT,INSERT,DELETE ON public.agente_gerencial_conversas TO authenticated;
GRANT ALL ON public.agente_gerencial_conversas TO service_role;
ALTER TABLE public.agente_gerencial_conversas ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversas_proprias ON public.agente_gerencial_conversas FOR ALL TO authenticated USING (user_id=auth.uid() AND (SELECT public.pode_agente_gerencial())) WITH CHECK (user_id=auth.uid() AND (SELECT public.pode_agente_gerencial()));
CREATE INDEX agente_gerencial_conversas_user ON public.agente_gerencial_conversas(user_id,updated_at DESC,id);
CREATE TABLE public.agente_gerencial_mensagens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversa_id uuid NOT NULL REFERENCES public.agente_gerencial_conversas(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('user','assistant')), parts jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.agente_gerencial_mensagens TO authenticated;
GRANT ALL ON public.agente_gerencial_mensagens TO service_role;
ALTER TABLE public.agente_gerencial_mensagens ENABLE ROW LEVEL SECURITY;
CREATE POLICY mensagens_proprias ON public.agente_gerencial_mensagens FOR SELECT TO authenticated USING (user_id=auth.uid() AND (SELECT public.pode_agente_gerencial()) AND EXISTS (SELECT 1 FROM public.agente_gerencial_conversas c WHERE c.id=conversa_id AND c.user_id=auth.uid()));
CREATE INDEX agente_gerencial_mensagens_conversa ON public.agente_gerencial_mensagens(conversa_id,created_at,id);
CREATE VIEW public.agente_gerencial_dados AS
SELECT 'notas'::text dataset,n.id::text row_id,n.created_at data_ref,jsonb_build_object('nf',n.numero_nf,'serie',n.serie,'emissao',n.data_emissao,'entrada',n.created_at,'embarcador',n.razao_social_emitente,'cliente',n.dest_razao_social,'cidade',n.dest_cidade,'uf',n.dest_uf,'status',n.status_entrega,'peso_kg',n.peso_bruto,'volume_m3',n.volume_m3,'valor_mercadoria',n.valor_nf,'caixas',CASE WHEN i.cesta AND n.qtd_volumes>0 THEN n.qtd_volumes ELSE i.caixas END,'agenda_status',a.status,'agenda_data',a.data_agendamento,'placa',v.placa,'roteirizacao_data',v.data,'carga_status',c.status,'carga_data',c.data,'tipo_carga',c.tipo_carga,'dias_permanencia',((now() AT TIME ZONE 'America/Sao_Paulo')::date-(n.created_at AT TIME ZONE 'America/Sao_Paulo')::date)) dados
FROM public.notas_fiscais n LEFT JOIN public.cargas c ON c.id=n.carga_id LEFT JOIN LATERAL (SELECT sum(ceil(q_com)) caixas,bool_or(x_prod ~* '\m(emb\.?|embalagem)\s*cesta\M') cesta FROM public.itens_nf WHERE nf_id=n.id) i ON true LEFT JOIN LATERAL (SELECT status,data_agendamento FROM public.agendamentos WHERE nf_id=n.id ORDER BY created_at DESC,id DESC LIMIT 1) a ON true LEFT JOIN LATERAL (SELECT ve.placa,ve.data FROM public.veiculo_nfs vn JOIN public.veiculos ve ON ve.id=vn.veiculo_id WHERE vn.nf_id=n.id ORDER BY ve.data DESC,ve.id DESC LIMIT 1) v ON true
UNION ALL SELECT 'cargas',id::text,data::timestamptz,jsonb_build_object('data',data,'placa',placa,'motorista',motorista,'status',status,'tipo_carga',tipo_carga) FROM public.cargas
UNION ALL SELECT 'veiculos',id::text,data::timestamptz,jsonb_build_object('data',data,'placa',placa,'motorista',motorista,'status',status,'capacidade_kg',capacidade_kg,'capacidade_m3',capacidade_m3,'prestacao_contas_em',prestacao_contas_em) FROM public.veiculos
UNION ALL SELECT 'agendas',a.id::text,coalesce(a.data_agendamento::timestamptz,a.created_at),jsonb_build_object('nf',n.numero_nf,'cliente',n.dest_razao_social,'embarcador',n.razao_social_emitente,'status',a.status,'data',a.data_agendamento,'ocorrencia',a.ocorrencia) FROM public.agendamentos a JOIN public.notas_fiscais n ON n.id=a.nf_id
UNION ALL SELECT 'entregas',b.id::text,b.registrado_em,jsonb_build_object('nf',n.numero_nf,'cliente',n.dest_razao_social,'embarcador',n.razao_social_emitente,'placa',v.placa,'data',b.registrado_em,'status',b.status,'ocorrencia',b.ocorrencia,'conferencia_status',b.conferencia_status,'validacao_status',b.validacao_status,'canhoto_pendente_motivo',b.canhoto_pendente_motivo) FROM public.baixas_entrega b JOIN public.notas_fiscais n ON n.id=b.nf_id LEFT JOIN public.veiculos v ON v.id=b.veiculo_id
UNION ALL SELECT 'ibac',p.chave,coalesce(p.data_entrega,p.consultado_em),jsonb_build_object('nf',p.numero_nf,'cliente',n.dest_razao_social,'embarcador',n.razao_social_emitente,'data',p.data_entrega,'status',p.status_portal,'validacao_status',p.status_validacao,'possui_imagem',p.possui_imagem,'motivo',p.justificativa,'consultado_em',p.consultado_em) FROM public.ibac_portal_validacao p LEFT JOIN public.notas_fiscais n ON n.chave_acesso=p.chave
UNION ALL SELECT 'okentrega',q.id::text,q.created_at,jsonb_build_object('nf',q.numero_nf,'cliente',n.dest_razao_social,'embarcador',n.razao_social_emitente,'data',q.created_at,'status',q.status,'status_baixa',q.status_baixa,'validacao_status',q.status_comprovante,'motivo',q.motivo_recusa,'enviado_em',q.enviado_em,'validado_em',q.validado_em) FROM public.okentrega_queue q LEFT JOIN public.notas_fiscais n ON n.id=q.nf_id
UNION ALL SELECT 'produtos',p.id::text,p.created_at,jsonb_build_object('codigo',p.codigo,'descricao',p.descricao,'categoria',p.categoria,'embarcador',e.razao_social,'ativo',p.ativo,'peso_bruto_cx_kg',p.peso_bruto_cx_kg,'volume_m3',p.volume_m3,'largura_mm',p.largura_mm,'altura_mm',p.altura_mm,'comprimento_mm',p.comprimento_mm) FROM public.produtos p LEFT JOIN public.embarcadores e ON e.id=p.embarcador_id
UNION ALL SELECT 'destinatarios',id::text,created_at,jsonb_build_object('cliente',razao_social,'nome_fantasia',nome_fantasia,'ativo',ativo) FROM public.destinatarios
UNION ALL SELECT 'embarcadores',id::text,created_at,jsonb_build_object('embarcador',razao_social,'nome_fantasia',nome_fantasia,'cidade',municipio,'uf',uf,'ativo',ativo,'sla_padrao_horas',sla_padrao_horas) FROM public.embarcadores
UNION ALL SELECT 'roteirizacoes',id::text,created_at,jsonb_build_object('data',created_at,'status',status,'distancia_total_km',distancia_total_km,'tempo_estimado_min',tempo_estimado_min,'peso_kg',peso_total_kg,'volume_m3',volume_total_m3) FROM public.roteirizacoes
UNION ALL SELECT 'prefaturas',id::text,data_recebimento::timestamptz,jsonb_build_object('cliente',cliente_nome,'numero',numero_prefatura_cliente,'data',data_recebimento,'periodo_inicio',periodo_inicio,'periodo_fim',periodo_fim,'status',status,'total_itens',total_itens,'valor_mercadoria',total_valor_nf_cliente,'valor_frete',total_valor_frete_cliente) FROM public.prefaturas
UNION ALL SELECT 'prefatura_itens',i.id::text,p.data_recebimento::timestamptz,jsonb_build_object('cliente',p.cliente_nome,'prefatura',p.numero_prefatura_cliente,'nf',i.numero_nf_cliente,'serie',i.serie_cliente,'emissao',i.data_emissao_cliente,'valor_mercadoria',i.valor_nf_cliente,'valor_frete',i.valor_frete_cliente,'peso_kg',i.peso_cliente,'caixas',i.volumes_cliente) FROM public.prefatura_itens i JOIN public.prefaturas p ON p.id=i.prefatura_id
UNION ALL SELECT 'ctes',id::text,coalesce(data_emissao::timestamptz,created_at),jsonb_build_object('numero',numero_cte,'nf',numero_nf_referenciada,'embarcador',razao_social_emitente,'emissao',data_emissao,'valor_frete',valor_frete,'tipo_documento',tipo_documento) FROM public.ctes;
REVOKE ALL ON public.agente_gerencial_dados FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.agente_gerencial_consultar(p_dataset text,p_inicio date,p_fim date,p_filtros jsonb DEFAULT '{}'::jsonb,p_offset integer DEFAULT 0) RETURNS TABLE(row_id text,dados jsonb) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public SET statement_timeout='15s' AS $$
BEGIN
IF NOT (SELECT public.pode_agente_gerencial()) THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF;
IF p_inicio IS NULL OR p_fim IS NULL OR p_fim<p_inicio OR p_fim-p_inicio>366 OR p_offset<0 OR p_offset>5000 OR p_dataset NOT IN ('notas','cargas','veiculos','agendas','entregas','ibac','okentrega','produtos','destinatarios','embarcadores','roteirizacoes','prefaturas','prefatura_itens','ctes') OR jsonb_typeof(p_filtros)<>'object' THEN RAISE EXCEPTION 'Consulta inválida'; END IF;
IF EXISTS(SELECT 1 FROM jsonb_each_text(p_filtros) WHERE key NOT IN ('nf','placa','cliente','embarcador','status','validacao_status','cidade','codigo','agenda_status','roteirizacao_data') OR length(value)>120) THEN RAISE EXCEPTION 'Filtro não autorizado'; END IF;
RETURN QUERY SELECT d.row_id,d.dados FROM public.agente_gerencial_dados d WHERE d.dataset=p_dataset AND (p_dataset IN ('produtos','destinatarios','embarcadores') OR (d.data_ref >= (p_inicio::timestamp AT TIME ZONE 'America/Sao_Paulo') AND d.data_ref < ((p_fim+1)::timestamp AT TIME ZONE 'America/Sao_Paulo'))) AND NOT EXISTS(SELECT 1 FROM jsonb_each_text(p_filtros) f WHERE CASE WHEN f.key IN ('nf','placa','codigo','roteirizacao_data') THEN lower(coalesce(d.dados->>f.key,''))<>lower(f.value) ELSE position(lower(f.value) in lower(coalesce(d.dados->>f.key,'')))=0 END) ORDER BY d.row_id LIMIT 500 OFFSET p_offset;
END $$;
REVOKE ALL ON FUNCTION public.agente_gerencial_consultar(text,date,date,jsonb,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.agente_gerencial_consultar(text,date,date,jsonb,integer) TO authenticated;
CREATE FUNCTION public.agente_gerencial_reservar(p_conversa uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
IF NOT (SELECT public.pode_agente_gerencial()) THEN RETURN false; END IF;
UPDATE public.agente_gerencial_conversas SET executando_em=now() WHERE id=p_conversa AND user_id=auth.uid() AND (executando_em IS NULL OR executando_em<now()-interval '5 minutes');
RETURN FOUND;
END $$;
REVOKE ALL ON FUNCTION public.agente_gerencial_reservar(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.agente_gerencial_reservar(uuid) TO authenticated;